// 只记录真实执行，不凭空生成 trace，不改业务函数。
function recordNode(
  nodeName: string,
  fn: (s: QuoteState) => Record<string, number | string>,
  log: NodeRecord[],
  trace: Record<string, any>[],
): (s: QuoteState) => Record<string, number | string> {
  return (s: QuoteState) => {
    const started = Date.now()
    try {
      const output = fn(s)
      log.push({ node: nodeName, output: { ...output } })
      trace.push({ node: nodeName, status: 'completed', elapsed_ms: Date.now() - started })
      return output
    } catch (error) {
      trace.push({ node: nodeName, status: 'failed', elapsed_ms: Date.now() - started })
      throw error
    }
  }
}

function buildQuoteGraph(log: NodeRecord[], trace: Record<string, any>[]): any {
  return new StateGraph(State)
    .addNode('bulk', recordNode('bulk', bulkNode, log, trace))
    .addNode('regular', recordNode('regular', regularNode, log, trace))
    .addNode('calc_tax', recordNode('calc_tax', taxNode, log, trace))
    .addNode('calc_shipping', recordNode('calc_shipping', shippingNode, log, trace))
    .addNode('join', recordNode('join', joinNode, log, trace))
    .addConditionalEdges(START, (s: QuoteState) => (s.quantity >= 10 ? 'bulk' : 'regular'), ['bulk', 'regular'])
    .addEdge('bulk', 'calc_tax')
    .addEdge('bulk', 'calc_shipping')
    .addEdge('regular', 'calc_tax')
    .addEdge('regular', 'calc_shipping')
    .addEdge(['calc_tax', 'calc_shipping'], 'join')
    .addEdge('join', END)
    .compile()
}

